from collections import defaultdict
def solve(inp):
    N=len(inp)
    offs=defaultdict(list)
    for r in range(N):
        for c in range(N):
            if inp[r][c]: offs[inp[r][c]].append(r-c)
    p=2
    while True:
        seen=set(); ok=True
        for ds in offs.values():
            for d in ds:
                if d%p in seen: ok=False; break
                seen.add(d%p)
            if not ok: break
        if ok: break
        p+=1
    # background = most frequent input color
    bg=Counter(x for row in inp for x in row if x).most_common(1)[0][0]
    out=[[bg]*N for _ in range(N)]
    for v,ds in offs.items():
        base=ds[0]%p
        for r in range(N):
            for c in range(N):
                if (r-c)%p==base: out[r][c]=v
    return out
